%#codegen
function [residual, predicted] = neuron_predictor_fixpt(x_in, reset)
% NEURON_PREDICTOR Optimized LMS predictive coding neuron
% Uses explicit parallel MAC tree + fabric adders for low latency & positive slack.

fm = get_fimath();

NUM_TAPS    = fi(4, 0, 3, 0, fm);
SCALE_UP    = fi(4096, 0, 13, 0, fm);    % 2^12
INV_SCALE   = fi(1/4096, 0, 14, 25, fm);  % 2^-12
MU_STEP     = fi(1/1024, 0, 14, 23, fm); % 2^-14

persistent x_hist w b;

x_val = fi(double(x_in), 1, 11, 0, fm);

if isempty(x_hist) || reset
    x_hist = fi(zeros(fi_toint(NUM_TAPS), 1), 1, 11, 0, fm);
    w = fi(zeros(fi_toint(NUM_TAPS), 1), 1, 14, 0, fm);
    w(1) = SCALE_UP; % 4096 (represents 1.0 in Q12)
    b = fi(0, 1, 13, 0, fm);
end

% --- HLS Synthesis Directives ---
coder.hdl.literaltext("#pragma HLS ARRAY_PARTITION variable=x_hist complete dim=1");
coder.hdl.literaltext("#pragma HLS ARRAY_PARTITION variable=w complete dim=1");

% --- 1. Parallel Multiplication (Mapped to DSPs) ---
prod = fi(zeros(fi_toint(NUM_TAPS), 1), 1, 24, 0, fm);
coder.hdl.literaltext("#pragma HLS ARRAY_PARTITION variable=prod complete dim=1");

coder.hdl.loopspec('unroll');
for i = fi(1, 0, 1, 0, fm):NUM_TAPS
    prod(i) = x_hist(i) * w(i);
    coder.hdl.literaltext("#pragma HLS BIND_OP variable=prod op=mul impl=dsp");
end

% --- 2. Balanced Parallel Adder Tree (Mapped to Fabric) ---
sum_01 = fi(prod(1) + prod(2), 1, 24, 0, fm);
sum_23 = fi(prod(3) + prod(4), 1, 22, 0, fm);
acc    = fi(b + (sum_01 + sum_23), 1, 24, 0, fm);
coder.hdl.literaltext("#pragma HLS BIND_OP variable=acc op=add impl=fabric");

predicted = fi(floor(acc * INV_SCALE), 1, 12, 0, fm);

% --- 3. Residual Error ---
residual = fi(x_val - predicted, 1, 10, 0, fm);

% --- 4. Adaptive LMS Update (Power-of-2 scaling -> bit-shifts) ---
b(:) = b + floor((residual * SCALE_UP) * MU_STEP);

coder.hdl.loopspec('unroll');
for i = fi(1, 0, 1, 0, fm):NUM_TAPS
    grad = fi(residual * x_hist(i), 1, 19, 0, fm);
    coder.hdl.literaltext("#pragma HLS BIND_OP variable=grad op=mul impl=dsp");
    w(i) = w(i) + floor(grad * MU_STEP);
end

% --- 5. Update Delay Line ---
coder.hdl.loopspec('unroll');
for i = NUM_TAPS:fi(-1, 1, 2, 0, fm):fi(2, 0, 2, 0, fm)
    x_hist(i) = x_hist(i-fi(1, 0, 1, 0, fm));
end
x_hist(1) = x_val;
end



function y = fi_toint(u)
    coder.inline( 'always' );
    if isfi( u )
        nt = numerictype( u );
        s = nt.SignednessBool;
        wl = nt.WordLength;
        if s
            y = int32( fi( u, s, wl, 0, hdlfimath ) );
        else
            y = uint32( fi( u, s, wl, 0, hdlfimath ) );
        end
    else
        y = int32( u );
    end
end

function fm = get_fimath()
	fm = fimath('RoundingMethod', 'Floor',...
	     'OverflowAction', 'Wrap',...
	     'ProductMode','FullPrecision',...
	     'SumMode','FullPrecision');
end
